parameters.jsCode:
const body = $json.body || $json;

const typeWebhook = body.typeWebhook || '';
if (typeWebhook !== 'incomingMessageReceived') {
  return [];
}

const chatId = body.senderData?.chatId || '';
const senderName = body.senderData?.senderName || '';
const typeMessage = body.messageData?.typeMessage || '';

let chatInput = '';
if (typeMessage === 'textMessage') {
  chatInput = body.messageData?.textMessageData?.textMessage || '';
} else if (typeMessage === 'extendedTextMessage') {
  chatInput = body.messageData?.extendedTextMessageData?.text || '';
}

const wid = chatId.replace('@c.us', '');
let phone = wid.startsWith('972') ? '0' + wid.slice(3) : wid;

const hasFile = ['documentMessage', 'imageMessage'].includes(typeMessage);
const fileUrl = hasFile ? (body.messageData?.fileMessageData?.downloadUrl || '') : '';
const fileName = hasFile ? (body.messageData?.fileMessageData?.fileName || 'file.pdf') : '';

return [{
  json: {
    chatId,
    chatInput,
    phone_number: phone,
    phone_is_valid: /^05\d{8}$/.test(phone),
    has_pdf: hasFile && fileUrl !== '',
    file_url: fileUrl,
    file_name: fileName,
    sender_name: senderName
  }
}];

const raw = $input.first().json.text || $input.first().json.output || '';
const clean = raw.replace(/```json|```/g, '').trim();

let data;
try {
  data = JSON.parse(clean);
} catch(e) {
  const m = clean.match(/\{[\s\S]*?\}/);
  try { data = m ? JSON.parse(m[0]) : { full_name: 'לא זוהה', codes: '', phone: '' }; }
  catch(e2) { data = { full_name: 'לא זוהה', codes: '', phone: '' }; }
}

const chatId = $('Parse WhatsApp Input').first().json.chatId || '';
const wid = chatId.replace('@c.us', '');
let phoneFromChat = wid.startsWith('972') ? '0' + wid.slice(3) : wid;

const normalize = s => (s || '').replace(/[-\s]/g, '');
const fromPdf = normalize(data.phone || '').match(/05\d{8}/);
const phone = phoneFromChat || (fromPdf && fromPdf[0]) || '';

const codesArray = (data.codes || '')
  .split(/[,;\s]+/)
  .map(s => s.trim())
  .filter(s => /^\d{4,6}$/.test(s));

return [{
  json: {
    phone_number: phone,
    phone_is_valid: /^05\d{8}$/.test(phone),
    full_name: data.full_name || 'לא זוהה',
    codes_array: codesArray,
    codes_count: codesArray.length
  }
}];

const profileId = $('Get Profile ID').first().json.id;
const codesArray = $('Parse PDF Data').first().json.codes_array;

if (!codesArray || codesArray.length === 0) {
  return [{ json: { user_id: profileId, code: '__empty__', skip: true } }];
}

return codesArray.map(code => ({
  json: { user_id: profileId, code: code, skip: false }
}));

